    if n == 0:
        return A
    # Small tensors: tiny BLOCK to minimize fixed launch/compile overhead.
    # Large tensors: deep BLOCK=9728 tiles to overlap the memory pipeline;
    # 9728 is the largest tile that compiles under flagtree's UB limit
    # (>=10240 fails) and is measured faster than 8192 for all dtypes.
