    native_mul = A.dtype == torch.float16

    if A.is_contiguous():
        _mish_persist_kernel[grid](A.reshape(-1), n, BLOCK=BLOCK, NATIVE_MUL=native_mul)
        return A

    ndim = A.dim()
    dev = A.device
    nd = max(ndim, 1)
    shape_t = torch.ones(nd, dtype=torch.int64, device=dev)
    stride_t = torch.zeros(nd, dtype=torch.int64, device=dev)
    if ndim > 0:
        shape_t[:ndim] = torch.tensor(A.shape, dtype=torch.int64, device=dev)
        stride_t[:ndim] = torch.tensor(A.stride(), dtype=torch.int64, device=dev)

    _mish_persist_strided_kernel[grid](A, shape_t, stride_t, n, NDIM=nd, BLOCK=BLOCK)
    return A
